import {BUILD,SKILLS,LOCS,SLOTS,SLOTNAME,RARITY,fresh,stats,preset,encounter,step,reward,offline,forge,item,validSave} from './engine.js';
import {drawScene} from './art.js';
const $=id=>document.getElementById(id),KEY='ashencrown-v1';let s;try{let raw=localStorage.getItem(KEY);s=raw?JSON.parse(raw):fresh();if(!validSave(s))throw Error();}catch{s=fresh();}let e=null,tab='skills',logs=[],selection=[],nextAt=0,lastStep=0,toastTimer,hitUntil=0;const away=offline(s);const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){s.lastSeen=Date.now();try{localStorage.setItem(KEY,JSON.stringify(s));$('saveStatus').textContent='已自动保存';}catch{$('saveStatus').textContent='存档失败，请导出备份';}}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function modal(html){$('modalBody').innerHTML=html;$('modal').showModal();} $('closeModal').onclick=()=>$('modal').close();$('modal').addEventListener('click',ev=>{if(ev.target===$('modal'))$('modal').close();});
function gearHtml(i){let on=s.equip[i.slot]===i.id;return `<article class="gear ${on?'equipped':''}"><div class="gearHead"><h4 class="r${i.rarity}">${esc(i.name)}${i.bless?' +'+i.bless:''}</h4><span>${i.locked?'◆':''}</span></div><small>${RARITY[i.rarity]} · ${SLOTNAME[i.slot]} · Lv.${i.level} ${on?'／已装备':''}</small><p>攻击 ${i.atk+(i.bless||0)*2} · 护甲 ${i.armor} · 生命 ${i.hp}</p>${i.rarity===4?'<p class="r4">王烬：命中附加目标最大生命 1% 伤害，上限为自身攻击 60%。</p>':''}<p>${i.set?BUILD.find(b=>b.id===i.set).name+'套装':'独立装备 · 更高属性同样有用'}</p><button data-equip="${i.id}" ${on?'disabled':''}>${on?'已装备':'装备'}</button><button data-lock="${i.id}">${i.locked?'解锁':'锁定'}</button><button data-sell="${i.id}" ${on||i.locked?'disabled':''}>出售 +${10+i.rarity*8}</button></article>`;}
function render(){let st=stats(s);$('level').textContent='Lv.'+s.level;$('xpText').textContent=s.xp+' / '+s.level*80;$('xpBar').style.width=s.xp/(s.level*80)*100+'%';$('stats').innerHTML=`<div><b>${st.atk}</b><span>攻击</span></div><div><b>${st.armor}</b><span>护甲</span></div><div><b>${st.hp}</b><span>生命</span></div>`;$('gold').textContent=s.gold.toLocaleString();$('talentCount').textContent='· '+Math.max(0,s.level-1-Object.values(s.talents).reduce((a,b)=>a+b,0))+' 点';$('buildPicker').innerHTML=BUILD.map((b,i)=>`<button class="buildCard ${s.build===b.id?'active':''}" data-build="${b.id}"><span class="runeIcon">${['⚒','♨','▣'][i]}</span><span><strong>${b.name}</strong><small>${b.sub}</small></span></button>`).join('');$('locations').innerHTML=LOCS.map((l,i)=>`<button class="location ${s.location===i?'active':''}" data-location="${i}"><strong>${l.name}</strong><span>0${i+1}</span><small>${l.mat} · 推荐 Lv.${[1,3,5][i]}</small></button>`).join('');$('sceneTitle').textContent=LOCS[s.location].name;$('sceneSubtitle').textContent=LOCS[s.location].en;$('runBtn').textContent=s.running?'Ⅱ 暂停远征':'▶ 开始远征';$('bagCount').textContent=s.inventory.length;$('questList').innerHTML=LOCS.map((l,i)=>`<div class="quest ${s.bossWins[i]?'done':''}"><div><strong>${s.bossWins[i]?'✓':'0'+(i+1)} ${l.name}</strong><p>${['追踪货单，击败灰旗首领','调查炉心，找回封印碎片','面对守誓者，揭开旧约'][i]}</p></div></div>`).join('');renderHud();renderTab();}
function renderHud(){let st=stats(s),hp=e?e.heroHp:st.hp;$('heroHp').textContent=Math.ceil(hp)+' / '+st.hp;$('heroHpBar').style.width=Math.min(100,hp/st.hp*100)+'%';$('enemyName').textContent=e?e.name:'等待出发';$('enemyHp').textContent=e?Math.max(0,Math.ceil(e.hp))+' / '+e.max:'—';$('enemyHpBar').style.width=(e?Math.max(0,e.hp/e.max*100):0)+'%';$('roundNum').textContent=e?'回合 '+e.round:'';$('battleState').textContent=s.running?(e?.boss?'首领战 · 自动战斗':'远征中 · 自动战斗'):'营地休整';let cd=Math.max(0,Math.ceil((s.bossReady[s.location]-Date.now())/1000));$('bossBtn').textContent=cd?'♜ 奖励冷却 '+cd+'s':'♜ 挑战首领';$('bossBtn').disabled=cd>0||!!(e?.boss&&!e.done);$('battleLog').innerHTML=logs.length?logs.slice(0,14).map(t=>'<p>'+esc(t)+'</p>').join(''):'<p class="muted">旅程尚未开始。</p>';}
function renderTab(){let st=stats(s),content='';if(tab==='skills'){content=`<div class="tabTop"><p>装备 3 个技能，按从上到下的优先级自动施放。冷却时使用普攻。</p><span class="pill">可自由混搭</span></div><div class="setBonus">${BUILD.map(b=>`${b.name} ${st.count[b.id]||0}/4`).join('　·　')}<br>${BUILD.filter(b=>(st.count[b.id]||0)>=2).map(b=>b.bonus).join('<br>')||'穿戴同套 2 / 4 件即可获得套装加成。'}</div>`+s.skills.map((k,i)=>`<div class="skillRow"><span class="skillNumber">0${i+1}</span><span class="skillRune">${SKILLS[k].icon}</span><div class="skillMain"><select aria-label="第${i+1}技能" data-skill="${i}">${Object.entries(SKILLS).map(([key,v])=>`<option value="${key}" ${k===key?'selected':''}>${v.name}</option>`).join('')}</select><p>${SKILLS[k].desc}</p></div><div class="skillCondition"><select aria-label="第${i+1}技能条件" data-condition="${i}">${[['always','可用即施放'],['low','生命低于60%'],['charge','敌人将重击'],['burn','目标已灼烧']].map(([v,n])=>`<option value="${v}" ${s.conditions[i]===v?'selected':''}>${n}</option>`).join('')}</select><span class="cooldown">CD ${SKILLS[k].cd} 回合</span></div></div>`).join('');}if(tab==='inventory'){let eq=Object.values(s.equip);content=`<div class="tabTop"><p>装备 ${s.inventory.length} / 100 · 满包时不再拾取装备，金币与材料照常获得。</p><button id="sellAll" class="secondary">出售未锁定非套装</button></div><div class="gearGrid">`+[...s.inventory].sort((a,b)=>Number(eq.includes(b.id))-Number(eq.includes(a.id))||b.rarity-a.rarity).map(gearHtml).join('')+'</div>';}if(tab==='forge'){content=`<div class="tabTop"><div><h3>黑炉尚有余温</h3><p>放入 1—5 份材料。主要材料决定套装倾向，数量提高史诗概率。</p></div><span class="pill">规则融合 · 无 AI 调用</span></div><div class="materialList">${Object.entries(s.materials).map(([k,n])=>`<button data-material="${k}">${k} ×${n}<small>${{'铁屑':'金属 → 碎砧','炉火晶':'火焰 → 炉纹','誓约残片':'灵魂 → 守冢'}[k]}</small></button>`).join('')}</div><div class="forgeTray">${selection.length?selection.map((k,i)=>`<button data-remove="${i}">${k} ×</button>`).join(''):'<span class="muted tiny">点击材料加入熔炉，最多 5 份</span>'}</div><div class="row"><select id="forgeSlot" aria-label="锻造部位">${SLOTS.map(k=>`<option value="${k}">${SLOTNAME[k]}</option>`).join('')}</select><button id="forgeBtn" class="primary">融合锻造 · 40 金币</button><button id="blessBtn" class="secondary">祝福当前武器 · 30 金币</button></div><p class="tiny">基础结果为稀有；史诗概率 15% + 每份材料 4%；传说概率 2%。属性随角色等级小幅浮动。祝福每次 +2 攻击，最多 5 次。</p><div class="sideDivider"></div><h3>哥布林行商 · 尼克</h3><p class="tiny">“世界还在烧，生意总得做。”　本章补给剩余 ${s.stock} 份，不会无限刷新。</p><button id="buyBtn" class="secondary" ${s.stock<=0?'disabled':''}>购买材料包 · 25 金币</button>`;}if(tab==='journal'){content=`<div class="tabTop"><div><h3>风从五族的疆界吹来</h3><p>人类、矮人、精灵、哥布林与烬裔各自谋生。此版本以矮人篇为可玩切片。</p></div><span class="pill">已胜利 ${s.kills} 场</span></div>`+'<details class="mobileLog"><summary>最近战斗记录</summary>'+logs.slice(0,14).map(x=>'<p>'+esc(x)+'</p>').join('')+'</details>'+s.chronicle.map((c,i)=>`<div class="journalEntry"><small>CHRONICLE / ${String(s.chronicle.length-i).padStart(2,'0')}</small>${esc(c)}</div>`).join('')+'<p class="tiny">世界纪事为章节事件，不是完整政治模拟。离线驻扎最多结算 4 小时，仅获得金币、经验与材料，不自动击败首领。</p>';} $('tabContent').innerHTML=content;}
function resetFight(){e=null;nextAt=0;lastStep=Date.now();render();save();}function start(boss=false){s.running=true;e=encounter(s,boss);lastStep=Date.now();logs.unshift(boss?'首领现身：'+e.name:'遭遇 '+e.name);$('combatMessage').textContent=boss?'首领奖励胜利后冷却 60 秒，失败可立即重试。':'自动远征中：战斗 → 拾取 → 休整 → 再次出发。';render();save();}
$('runBtn').onclick=()=>{if(s.running){s.running=false;$('combatMessage').textContent='已暂停，当前战斗进度保留。';render();save();}else if(e&&!e.done){s.running=true;lastStep=Date.now();render();save();}else start();};$('bossBtn').onclick=()=>{if(Date.now()>=s.bossReady[s.location])start(true);};
document.addEventListener('click',ev=>{let b=ev.target.closest('button');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));renderTab();}if(b.dataset.build){preset(s,b.dataset.build);resetFight();toast('已切换 '+BUILD.find(x=>x.id===s.build).name+'：装备与技能预设已应用');}if(b.dataset.location!==undefined){s.location=+b.dataset.location;resetFight();toast(LOCS[s.location].desc);}if(b.dataset.equip){let it=s.inventory.find(x=>x.id===b.dataset.equip);s.equip[it.slot]=it.id;s.build='custom';resetFight();toast('已装备 '+it.name);}if(b.dataset.lock){let it=s.inventory.find(x=>x.id===b.dataset.lock);it.locked=!it.locked;save();renderTab();}if(b.dataset.sell){let it=s.inventory.find(x=>x.id===b.dataset.sell);if(it&&!it.locked&&s.equip[it.slot]!==it.id){s.gold+=10+it.rarity*8;s.inventory=s.inventory.filter(x=>x.id!==it.id);render();save();}}if(b.dataset.material){let k=b.dataset.material;if(selection.length>=5)return toast('最多放入 5 份材料');if(selection.filter(x=>x===k).length>=s.materials[k])return toast('该材料不足');selection.push(k);renderTab();}if(b.dataset.remove!==undefined){selection.splice(+b.dataset.remove,1);renderTab();}if(b.id==='forgeBtn'){let it=forge(s,selection,$('forgeSlot').value);if(!it)return toast('需要材料、40 金币以及空余行囊位置');selection=[];render();save();toast('锻造成功：'+RARITY[it.rarity]+' '+it.name);}if(b.id==='blessBtn'){let it=s.inventory.find(x=>x.id===s.equip.weapon);if(it.bless>=5)return toast('武器祝福已达上限');if(s.gold<30)return toast('金币不足');s.gold-=30;it.bless++;render();save();toast('祝福成功，武器攻击 +2');}if(b.id==='buyBtn'){if(s.gold<25)return toast('金币不足');if(!s.stock)return;s.gold-=25;s.stock--;for(let k in s.materials)s.materials[k]+=2;render();save();toast('获得每种材料各 2 份');}if(b.id==='sellAll'){let ids=Object.values(s.equip),sold=s.inventory.filter(x=>!x.set&&!x.locked&&!ids.includes(x.id));s.gold+=sold.reduce((a,x)=>a+10+x.rarity*8,0);s.inventory=s.inventory.filter(x=>!sold.includes(x));render();save();toast('已出售 '+sold.length+' 件非套装装备');}if(b.dataset.talent){let used=Object.values(s.talents).reduce((a,n)=>a+n,0);if(used>=s.level-1)return toast('升级后获得天赋点');s.talents[b.dataset.talent]++;save();render();showTalents();}});
document.addEventListener('change',ev=>{let el=ev.target;if(el.dataset.skill!==undefined){let i=+el.dataset.skill;if(s.skills.some((k,j)=>k===el.value&&j!==i)){toast('同一技能不能重复装备');return renderTab();}s.skills[i]=el.value;s.build='custom';resetFight();}if(el.dataset.condition!==undefined){s.conditions[+el.dataset.condition]=el.value;save();}});
function showTalents(){let points=s.level-1-Object.values(s.talents).reduce((a,b)=>a+b,0);let html=`<div class="eyebrow">DWARVEN LEGACY</div><h2>黑炉血脉</h2><p>每升一级获得 1 点天赋。剩余 ${points} 点。</p>`+[['power','锻锤之力','每点 +3 攻击'],['heart','山脉之心','每点 +20 生命'],['steel','钢铁之躯','每点 +3 护甲']].map(([k,n,d])=>`<div class="modalChoice"><div><h4>${n} · ${s.talents[k]}</h4><p>${d}</p></div><button data-talent="${k}" ${points<=0?'disabled':''}>提升</button></div>`).join('');html+='<p><button id="resetTalentBtn" class="secondary">免费重置天赋</button></p>';$('modalBody').innerHTML=html;$('resetTalentBtn').onclick=()=>{s.talents={power:0,heart:0,steel:0};resetFight();showTalents();toast('天赋已重置，点数全部返还');};if(!$('modal').open)$('modal').showModal();} $('talentBtn').onclick=showTalents;
$('helpBtn').onclick=()=>modal(`<div class="eyebrow">WELCOME, FORGEBEARER</div><h2>炉火未熄，旅途开始。</h2><p>你是矮人布洛克。一份存档只有这一名主角，其他种族将在故事中与你交汇。</p><ol><li>选择碎砧、炉纹或守冢，三套初始套装可自由切换。</li><li>点击“开始远征”自动战斗，收集金币、经验与材料。</li><li>装备战利品，调整三个技能的顺序与触发条件。</li><li>挑战三地首领，找回失踪商队的线索。失败无奖励冷却。</li><li>在融合锻炉打造新装备，升级后分配天赋。</li></ol><p>无硬性流派免疫。远征开启后离线会获得最多 4 小时的驻扎收益；保存仅限当前浏览器。此版为矮人玩法验证切片。</p><button class="primary" id="beginBtn">踏上旅途</button>`);
$('settingsBtn').onclick=()=>{modal('<h2>旅途存档</h2><p>进度保存在当前浏览器，建议导出备份。此版不提供云同步。</p><div class="row"><button id="exportBtn">导出存档</button><button id="importBtn">导入存档</button><button id="restartBtn" class="danger">重新开始</button></div><input id="importFile" type="file" accept="application/json" hidden>');$('exportBtn').onclick=()=>{save();let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(s)],{type:'application/json'}));a.download='灰冠诸境-布洛克.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};$('importBtn').onclick=()=>$('importFile').click();$('importFile').onchange=async ev=>{try{let v=JSON.parse(await ev.target.files[0].text());if(!validSave(v)||v.version!==1||!Array.isArray(v.inventory)||v.inventory.length>100||!Array.isArray(v.skills)||v.skills.length!==3||v.skills.some(x=>!SKILLS[x])||!Number.isFinite(v.gold)||v.gold<0||!Number.isInteger(v.location)||v.location<0||v.location>2||!v.equip||!v.materials||!v.talents||!Array.isArray(v.chronicle))throw Error();if(!confirm('导入将覆盖当前进度，确定继续？'))return;s=v;s.running=false;e=null;save();render();$('modal').close();toast('存档已导入');}catch{toast('存档格式无效，未覆盖当前进度');}};$('restartBtn').onclick=()=>{if(confirm('确定清除当前旅程并重新开始？此操作不能撤销，建议先导出。')){s=fresh();e=null;logs=[];selection=[];save();render();$('modal').close();toast('新的旅程已经开始');}};};document.addEventListener('click',ev=>{if(ev.target.id==='beginBtn'){$('modal').close();start();}});
function tick(now){if(document.hidden)return;if(s.running&&now-lastStep>1100){lastStep=now;if(!e||e.done){if(now>=nextAt)start(false);}else{logs.unshift(...step(s,e).reverse());logs=logs.slice(0,30);hitUntil=now+280;$('combatMessage').textContent=logs[0];if(e.done){if(e.win){let it=reward(s,e);let msg=e.boss?'首领已击败，获得线索与战利品。':'战斗胜利 · 收获 '+LOCS[s.location].mat;logs.unshift(msg);if(it)logs.unshift('获得 '+RARITY[it.rarity]+' '+it.name);$('combatMessage').textContent=msg;if(e.boss){s.running=false;toast('首领战胜利！新线索已记录在诸境纪事。');}}else{s.running=false;logs.unshift('你撤回营地。没有损失，也没有首领冷却。');$('combatMessage').textContent='战斗失败：提升装备或等级后重试，流派无需强制更换。';toast('已撤回营地，点击开始远征可恢复满生命');}nextAt=now+1800;render();save();}renderHud();}}}
let frame=0;function animate(t){if(t-frame>50){frame=t;drawScene($('scene'),{location:s.location,fighting:s.running&&!!e&&!e.done,boss:!!e?.boss,heroHp:e?e.heroHp/stats(s).hp:1,enemyHp:e?e.hp/e.max:1,time:t,hit:Date.now()<hitUntil});}requestAnimationFrame(animate);}render();requestAnimationFrame(animate);setInterval(()=>{tick(Date.now());renderHud();},250);setInterval(()=>{if(!document.hidden)save();},10000);window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();else{let r=offline(s);if(r){e=null;toast(`离线驻扎：+${r.gold} 金币，+${r.xp} 经验`);render();save();}}});
// Small, intentionally pixelated portrait drawn from the same visual vocabulary.
let pc=$('portrait').getContext('2d');pc.imageSmoothingEnabled=false;let rect=(x,y,w,h,c)=>{pc.fillStyle=c;pc.fillRect(x,y,w,h)};rect(44,108,74,7,'#111b15');rect(53,70,53,40,'#53654d');rect(48,76,15,24,'#768164');rect(100,76,16,24,'#768164');rect(62,32,37,32,'#b89d71');rect(55,27,50,12,'#697664');rect(61,18,37,12,'#828a6d');rect(77,13,9,27,'#c1aa6b');rect(60,49,43,12,'#c8b28a');rect(64,58,35,31,'#ae9b7b');rect(70,84,24,9,'#ae9b7b');rect(67,43,7,5,'#232d25');rect(88,43,7,5,'#232d25');rect(75,52,13,7,'#886743');rect(58,99,17,17,'#39483a');rect(89,99,17,17,'#39483a');rect(120,50,6,66,'#806343');rect(108,43,28,18,'#73806b');rect(110,43,24,4,'#a5ae87');rect(47,91,13,8,'#b89d71');
if(away)toast(`离线 ${away.minutes} 分钟：+${away.gold} 金币，+${away.xp} 经验，+${away.mat} 材料`);else if(!localStorage.getItem(KEY))$('helpBtn').click();save();
